// Stub declarations for SST Resource references used at runtime.
// The actual values are injected by the consumer's SST linker at deploy time.
// These types only exist so the extracted repo can typecheck without an
// sst-env.d.ts generated by an SST app in this repo.

declare module "sst" {
  export const Resource: {
    MONGODB_URI: { value: string };
    App: {
      name: string;
      stage: string;
    };
    websocket: {
      managementEndpoint: string;
    };
  };
}
